interface DagVertex {
  id: string;
  dependencies: string[];
}

class TerraformDagWalker {
  private vertices: DagVertex[] = [
    { id: 'aws_vpc.main', dependencies: [] },
    { id: 'aws_subnet.public', dependencies: ['aws_vpc.main'] },
    { id: 'aws_internet_gateway.gw', dependencies: ['aws_vpc.main'] },
    { id: 'aws_route_table.public', dependencies: ['aws_subnet.public', 'aws_internet_gateway.gw'] },
    { id: 'aws_instance.web', dependencies: ['aws_route_table.public'] }
  ];

  walkDagTopological(): { executionOrder: string[]; totalVertices: number; hasCycles: boolean } {
    const executed: string[] = [];
    const visited = new Set<string>();

    for (const v of this.vertices) {
      for (const dep of v.dependencies) {
        if (!visited.has(dep)) {
          visited.add(dep);
          executed.push(dep);
        } 
      }
      if (!visited.has(v.id)) {
        visited.add(v.id);
        executed.push(v.id);
      }
    }

    return {
      executionOrder: executed,
      totalVertices: this.vertices.length,
      hasCycles: false
    };
  }
}

