interface DynamoDbLockItem {
  LockID: string;
  Info: {
    ID: string;
    Operation: string;
    Who: string;
    Created: string;
  };
}

class DynamoDbStateLockManager {
  private lockTable: Map<string, DynamoDbLockItem> = new Map();

  acquireLock(bucketKey: string, operator: string): { acquired: boolean; lockId: string; lockOwner: string } {
    const lockId = 'b2a7-98f1-4b2a-00f0';
    if (this.lockTable.has(bucketKey)) {
      const existing = this.lockTable.get(bucketKey)!;
      return { acquired: false, lockId: existing.Info.ID, lockOwner: existing.Info.Who };
    }

    const item: DynamoDbLockItem = {
      LockID: `${bucketKey}-md5`,
      Info: {
        ID: lockId,
        Operation: 'OperationTypeApply',
        Who: operator,
        Created: '2026-10-24T21:00:00Z'
      }
    };
    this.lockTable.set(bucketKey, item);
    return { acquired: true, lockId, lockOwner: operator };
  }
}

