      name: config.name,
      allocatedStorageGb: config.allocatedStorageGb,
      backupRetentionDays: config.backupRetentionDays ?? 7,
      multiAz: config.multiAz ?? false
    };

    return {
      valid: errors.length === 0,
      validatedConfig: validated,
      errors
    };
  }
}

