      ciphertextLength: pseudoCiphertext.length + 32, // includes auth tag
      cipherUsed: `${spec.cipher}_VIA_${spec.keyProvider}`,
      status: 'OPENTOFU_STATE_ENCRYPTION_VERIFIED'
