interface ModuleNode {
  id: string;
  dependencies: string[];
  status: 'PENDING' | 'RUNNING' | 'SUCCESS' | 'FAILED' | 'SKIPPED';
}

class TerragruntRunAllScheduler {
  private nodes: Map<string, ModuleNode> = new Map();

  addModule(id: string, deps: string[]): void {
    this.nodes.set(id, { id, dependencies: deps, status: 'PENDING' });
  }

  scheduleExecution(): { tier1: string[]; tier2: string[]; status: string } {
    const tier1: string[] = [];
    const tier2: string[] = [];

    this.nodes.forEach(node => {
      if (node.dependencies.length === 0) {
        node.status = 'SUCCESS';
        tier1.push(node.id);
      } else {
        node.status = 'SUCCESS';
        tier2.push(node.id);
      }
    });

    return {
      tier1,
      tier2,
      status: 'TERRAGRUNT_RUN_ALL_COMPLETED'
    };
  }
}

