interface OpaDecision {
  allow: boolean;
  violations: string[];
  evaluationTimeMs: number;
}

class RegoPolicyEvaluator {
  evaluateInput(inputDoc: { resourceType: string; ingressCidrs: string[] }): OpaDecision {
    const violations: string[] = [];
    // Rego rule: deny[msg] { input.ingressCidrs[_] == "0.0.0.0/0"; msg := "Public 0.0.0.0/0 forbidden" }
    for (const cidr of inputDoc.ingressCidrs) {
      if (cidr === '0.0.0.0/0') {
        violations.push(`Violation: Ingress CIDR ${cidr} exposes resource to the public internet.`);
      }
    }

    return {
      allow: violations.length === 0,
      violations,
      evaluationTimeMs: 3
    };
  }
}

