}

class EnterpriseGovernanceValidator {
  private requiredTags = ['Environment', 'Owner', 'CostCenter'];

  validateGovernance(resource: TaggedResource): { approved: boolean; missingTags: string[]; kmsApproved: boolean } {
    const resourceTags = Object.keys(resource.tags);
    const missingTags = this.requiredTags.filter(t => !resourceTags.includes(t));

    const kmsApproved = !!resource.kmsKeyArn && resource.kmsKeyArn.startsWith('arn:aws:kms:');

    return {
      approved: missingTags.length === 0 && kmsApproved,
      missingTags,
      kmsApproved
    };
  }
}

