interface RegoRuleEvaluation {
  ruleName: string;
  passed: boolean;
  message: string;
}

class CapstonePolicySuite {
  evaluatePlan(plan: { resources: Array<{ type: string; encrypted: boolean; tags: Record<string, string>; ingressCidrs?: string[] }> }): { allPassed: boolean; ruleResults: RegoRuleEvaluation[] } {
    const results: RegoRuleEvaluation[] = [];

    for (const res of plan.resources) {
      // Rule 1: Encryption
      const encPassed = res.encrypted;
      results.push({
        ruleName: 'SEC-ENC-001',
        passed: encPassed,
        message: encPassed ? 'Resource encryption verified.' : `DENY [${res.type}]: Must enable KMS CMK encryption.`
      });

      // Rule 2: Mandatory Tags
      const hasTags = ['Environment', 'CostCenter'].every(t => !!res.tags[t]);
      results.push({
        ruleName: 'GOV-TAG-002',
        passed: hasTags,
        message: hasTags ? 'Mandatory tags verified.' : `DENY [${res.type}]: Missing required tags.`
      });
    }

    return {
      allPassed: results.every(r => r.passed),
      ruleResults: results
    };
  }
}

