interface DriftScanOutcome {
  component: string;
  exitCode: number;
  driftDetected: boolean;
  actionTaken: 'NOOP' | 'ALERT_DISPATCHED' | 'AUTO_RECONCILED';
}

class ContinuousDriftEngine {
  evaluateExitCode(component: string, exitCode: number, autoHealEnabled: boolean): DriftScanOutcome {
    if (exitCode === 2) {
      return {
        component,
        exitCode,
        driftDetected: true,
        actionTaken: autoHealEnabled ? 'AUTO_RECONCILED' : 'ALERT_DISPATCHED'
      };
    }
    return {
      component,
      exitCode,
      driftDetected: false,
      actionTaken: 'NOOP'
    };
  }
}

